const $=id=>document.getElementById(id), key='templar-eld ermere-v1'.replace(' ',''), fresh=()=>({coins:80,clues:[],inventory:[],placed:[],crafted:0,academy:0,solved:false,mode:'adventure',scene:'capital',minutes:9*60});const saveSystem=window.EldoriaSaves;let state=saveSystem.load(fresh);saveSystem.checkpoint();let scene=state.scene, pos={x:500,y:520},target=null,pending=null,t=0,last=0,sound=false,audio=null;
const scenes={capital:{name:'Eldoria, the lantern capital',sub:'An old kingdom. A new arrival. Eight missing names waiting to be remembered.',buildings:[['Royal Archive',170,235,'archive'],['Moonleaf Tavern',490,240,'tavern'],['Silverstitch Manor',800,230,'manor']]},workshop:{name:'The Shoemaker’s Quarter',sub:'Cut, stitch, enchant. Turn a small piece of leather into someone’s next adventure.',buildings:[['Silverstitch Workshop',250,250,'craft'],['Customer Counter',730,250,'orders']]},market:{name:'The Great Elf Market',sub:'Spend your mooncoins on things that become part of your home.',buildings:[['Moon & Moss Furnishings',250,250,'shop'],['The Traveling Merchant',730,250,'merchant']]},home:{name:'Your willowwood cottage',sub:'A quiet corner of the kingdom, belonging entirely to you.',buildings:[['Enter Your Cottage',490,220,'home']]},academy:{name:'The Academy of Moonlight',sub:'Learn the realm’s magic by making it work.',buildings:[['Herbal Alchemy',270,250,'potion'],['The Rune Observatory',730,250,'runes']]},forest:{name:'The Whispering Woods',sub:'Follow the river past the ordinary paths. Some secrets prefer to be found.',buildings:[['The Hollow Oak',230,270,'oak'],['The Moonwell',750,230,'well']]},forgotten:{name:'The Forgotten Quarter',sub:'A locked orphanage. Altered records. A family that never stopped looking.',buildings:[['Briar House Orphanage',300,235,'orphanage'],['Abandoned Carriage House',770,260,'carriage']]},festival:{name:'The Festival of Eight Lanterns',sub:'Music, glowing lanterns, and a gathering that remembers the children lost long ago.',buildings:[['Lantern Ceremony',270,250,'lantern'],['Festival Games',730,250,'game']]}};
