function awardAdventureCoins(amount,title='Adventure progress'){if(!Number.isFinite(amount)||amount<=0)return;if(window.deferAdventureReward)window.deferAdventureReward(amount,title);else state.coins+=amount;}
function advanceRealmTime(minutes){if(!Number.isFinite(minutes)||minutes<0)return;state.day=Number.isInteger(state.day)&&state.day>0?state.day:1;let total=state.minutes+minutes,days=Math.floor(total/1440);state.minutes=total%1440;if(days){state.day+=days;window.onNewRealmDay?.(days);}}
function setRealmTime(target){advanceRealmTime((target-state.minutes+1440)%1440);}
function persist(){state.scene=scene;saveSystem.write(state);renderUI()}
function toast(msg){$('toast').textContent=msg;$('toast').style.display='block';clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('toast').style.display='none',3500)}
function modal(title,html){$('modal').innerHTML=`<div style="display:flex;justify-content:space-between;align-items:start"><h2>${title}</h2><button id="close">✕</button></div>${html}`;$('close').onclick=()=>$('modal').close();if(!$('modal').open)$('modal').showModal()}
function action(label,fn){let b=document.createElement('button');b.textContent=label;b.onclick=fn;$('modal').append(b);return b}
function clue(id,title,text){modal(title,`<p>${text}</p><p class="pill">${state.clues.includes(id)?'Already recorded':'A new piece of the mystery'}</p>`);if(!state.clues.includes(id)){state.clues.push(id);awardAdventureCoins(15);persist();toast('Clue added to your journal · +15 mooncoins')}}
const evidence={archive:['The altered festival register','The royal register lists eight Silverstitch children arriving with their parents. A later entry claims they departed. Different ink, a forged signature, and no gatekeeper’s seal expose the lie.'],manor:['The parents’ search ledger','Lady Mirelle and Lord Aldren Silverstitch kept searching for years. Payments to investigators, letters to neighboring kingdoms, and eight untouched bedrooms prove the children were never abandoned.'],oak:['The silver-stitch heirloom','Inside a hollow oak you find a shoe clasp sewn with eight silver stitches. The same pattern appears on the original shoemaker elf’s tools. A note reads: “We share a beginning, even when they change our names.”'],orphanage:['The orphanage’s secret accounts','Briar House accepted eight children after the festival. Its director, Mistress Vey, erased their family names and sent them to separate households in exchange for jewels and silk. The records name the households and the receiving kingdom.'],carriage:['The cross-border carriage route','A hidden route map connects the festival’s service gate with Briar House in the neighboring kingdom of Thornmere. A hired carriage carried the children across the border. The driver was paid by Mistress Vey’s steward.'],merchant:['A survivor’s letter','Merchant Elian remembers a child called Nessa, forced to mend shoes in a wealthy household. Her letter describes seven siblings, a silver clasp, and festival lanterns. She is alive, and has begun searching for the others.']};
function enter(kind){if(evidence[kind]){if(kind==='orphanage'&&!state.clues.includes('archive')){modal('Briar House is locked','<p>The rusty door bears a royal seal. Find proof in the Royal Archive to obtain lawful access.</p>');return}clue(kind,...evidence[kind]);return}
if(kind==='craft')craft();else if(kind==='orders')modal('The customer counter',`<p>Orders are completed through the workshop’s four hands-on steps. Every finished pair pays 30 mooncoins.</p><p>Pairs delivered: ${state.crafted}. Your next customer is a forest courier who needs strong, quiet boots.</p>`);
else if(kind==='shop')shop();else if(kind==='home')home();else if(kind==='potion')potion();else if(kind==='runes')runes();else if(kind==='tavern'){modal('Moonleaf Tavern','<p>Innkeeper Fern sets down a warm cup. “The Silverstitches weren’t careless parents. Someone wanted those children to disappear. Ask who profited, traveler.”</p>');action('Enjoy a free supper',()=>{advanceRealmTime(60);persist();toast('A warm meal and an hour of peace');$('modal').close()})}else if(kind==='well'){modal('The Moonwell','<p>Water reflects the stars, even in daylight. Make a wish for the missing siblings, or simply sit beside the water.</p>');action('Sit by the moonwell',()=>{advanceRealmTime(120);persist();$('modal').close();toast('The forest grows still around you')})}else if(kind==='lantern'){modal('Eight lanterns, eight names','<p>The ceremony remembers children separated at the kingdom festival. Each lantern represents a life that still matters, even when records say otherwise.</p>');action('Light a lantern',()=>{toast('Your lantern rises above the trees');$('modal').close()})}else if(kind==='game')festivalGame()}
let craftStep=0,craftChoice='';function craft(){craftStep=0;craftScreen()}function craftScreen(){const steps=['Choose leather for the courier’s boots','Cut along the pattern','Stitch the boot panels','Choose a quiet-foot enchantment'];modal('At the workbench',`<small>Step ${craftStep+1} of 4</small><h3>${steps[craftStep]}</h3><p>${['Your courier will cross wet woodland paths. Choose a material.','Click the three pattern points in order.','Pull the silver thread through each stitch.','The courier needs to walk quietly without losing traction.'][craftStep]}</p><div id="craftarea" class="row"></div>`);let area=$('craftarea');if(craftStep===0){['Soft suede','Waxed leather','Silk'].forEach(x=>{let b=document.createElement('button');b.textContent=x;b.onclick=()=>{craftChoice=x;craftStep++;craftScreen()};area.append(b)})}else if(craftStep===1||craftStep===2){let n=0;for(let i=0;i<3;i++){let b=document.createElement('button');b.textContent=craftStep===1?`Cut point ${i+1}`:`Stitch ${i+1}`;b.onclick=()=>{if(i!==n){toast('Follow the pattern in order');return}b.disabled=true;n++;if(n===3){craftStep++;craftScreen()}};area.append(b)}}else{['Silent moss soles','Dancing sparkles','Heavy iron heels'].forEach(x=>{let b=document.createElement('button');b.textContent=x;b.onclick=()=>{if(x!=='Silent moss soles'){toast('The courier needs quiet soles. Try again.');return}state.crafted++;awardAdventureCoins(30);persist();modal('A pair worth the journey',`<p>Your ${craftChoice.toLowerCase()} boots fit perfectly. The courier pays 30 mooncoins and slips into the woods without a sound.</p>`);action('Make another pair',craft)};area.append(b)})}}
const items=[['lantern','Amber lantern',25,'🏮'],['rug','Woven woodland rug',40,'🧶'],['books','Fairy-tale bookshelf',55,'📚'],['plant','Moonfern planter',20,'🌿'],['harp','Elven harp',65,'🎵']];function shop(){modal('Moon & Moss Furnishings',`<p>Your balance: ${state.coins} mooncoins. Purchased items can be placed inside your cottage.</p>`);items.forEach(([id,name,price])=>{let b=action(`${name} · ${state.inventory.includes(id)?'Owned':price+' coins'}`,()=>{if(state.coins<price){toast('Earn more coins at the workshop or academy');return}state.coins-=price;state.inventory.push(id);persist();shop()});b.disabled=state.inventory.includes(id)})}
function home(){modal('Inside your cottage',`<div style="background:linear-gradient(#3d3729,#6d533a);padding:30px;border:4px solid #947650;border-radius:12px;text-align:center"><div style="font-size:55px">🪟</div><div style="font-size:38px">${state.placed.map(id=>items.find(x=>x[0]===id)[3]).join(' ')||'🪑'}</div><p style="color:#fff">Your peaceful willowwood home</p></div><p>Select an owned decoration to place or remove it.</p>`);items.filter(i=>state.inventory.includes(i[0])).forEach(([id,name])=>action((state.placed.includes(id)?'Remove ':'Place ')+name,()=>{state.placed=state.placed.includes(id)?state.placed.filter(x=>x!==id):[...state.placed,id];persist();home()}));if(!state.inventory.length)action('Visit the furniture market',()=>{$('modal').close();changeScene('market')})}
function potion(){modal('Herbal alchemy: a healing draught','<p>The recipe calls for moonleaf to soothe, springwater to carry the herbs, and honey to bind them. Select exactly those three ingredients.</p><div id="ingredients" class="row"></div>');let selected=new Set;['Moonleaf','Springwater','Honey','Dragon ash','Nightshade'].forEach(x=>{let b=document.createElement('button');b.textContent=x;b.onclick=()=>{selected.has(x)?selected.delete(x):selected.add(x);b.style.background=selected.has(x)?'#687046':''};$('ingredients').append(b)});action('Brew the draught',()=>{if(selected.size===3&&['Moonleaf','Springwater','Honey'].every(x=>selected.has(x))){awardAdventureCoins(20);state.academy++;persist();modal('The draught glows silver','<p>A balanced recipe! You earn 20 mooncoins and a completed academy lesson.</p>')}else toast('The mixture clouds. Check the recipe and try again.')})}
function runes(){modal('The rune observatory','<p>The gate inscription reads: “First comes the seed, then the tree, then its gift.” Arrange the runes by choosing them in that order.</p>');let seq=[];['Fruit','Seed','Tree'].forEach(x=>action(x,()=>{seq.push(x);if(seq.join(',')!=='Seed,Tree,Fruit'.split(',').slice(0,seq.length).join(',')){seq=[];toast('The runes fade. Start again.')}else if(seq.length===3){awardAdventureCoins(15);state.academy++;persist();modal('The gate opens','<p>The observatory’s stars brighten. +15 mooncoins. Growth takes time, just like the Silverstitch search.</p>')}else toast(`${x} accepted`)}))}
function festivalGame(){modal('Catch the lantern lights','<p>Catch five moving lights before the 15-second timer ends. Win 20 mooncoins.</p><div id="field" style="position:relative;height:230px;background:#0c1919;border-radius:10px"></div><p id="count"></p>');let caught=0,end=Date.now()+15000,b=document.createElement('button');b.textContent='✦';b.style.position='absolute';$('field').append(b);const move=()=>{b.style.left=Math.random()*75+'%';b.style.top=Math.random()*75+'%'};move();b.onclick=()=>{caught++;move();if(caught===5){clearInterval(timer);awardAdventureCoins(20);persist();modal('Five lights caught!','<p>The festival keeper awards you 20 mooncoins.</p>')}};let timer=setInterval(()=>{if(!$('count')){clearInterval(timer);return}$('count').textContent=`${caught}/5 lights · ${Math.max(0,Math.ceil((end-Date.now())/1000))} seconds`;move();if(Date.now()>end){clearInterval(timer);modal('The lanterns drift away','<p>There is always another round.</p>');action('Try again',festivalGame)}},850)}
function journal(){modal('Your evidence journal',`<p>${state.clues.length}/6 clues recovered. Your theory should connect the festival, the forged register, the orphanage, and the living survivors.</p>${state.clues.map(id=>`<div class="card"><h3>${evidence[id][0]}</h3><p>${evidence[id][1]}</p></div>`).join('')||'<p>Your journal is waiting for its first discovery. Start at the Royal Archive.</p>'}`);if(state.clues.length===6&&!state.solved){action('Accuse the parents of abandonment',()=>toast('The search ledger contradicts that theory.'));action('Expose Mistress Vey’s trafficking scheme',()=>{state.solved=true;awardAdventureCoins(100);persist();modal('The names return','<p>You present the register, accounts, route, heirloom, letter, and search ledger to the royal magistrate. Mistress Vey’s network is exposed. Search parties reach the eight households.</p><p>Months later, the siblings return to Silverstitch Manor. Reuniting does not erase the years of harm, but each is welcomed by their own name, with care and a choice about their future. Their parents’ search is finally over.</p><p>Elian’s letter reveals another clue: a glass rose engraved with the name of a different fairy-tale family. For now, Eldoria celebrates the eight reunited lives.</p><p>Case complete · +100 mooncoins.</p>')})}else if(state.solved)$('modal').insertAdjacentHTML('beforeend','<p class="pill">Silverstitch case solved · The family is reunited.</p>')}
function renderUI(){$('coins').textContent=`✧ ${state.coins} mooncoins`;$('clock').textContent=hour();$('mode').textContent=state.mode==='visit'?'☁ Just Visit mode':'⚿ Adventure mode';$('quest').innerHTML=state.mode==='visit'?'<div class="card"><p>No required tasks. Explore, make something, visit the tavern, or furnish your cottage at your own pace.</p></div>':`<div class="card"><p>${state.solved?'The eight siblings are home. Eldoria is yours to explore.':state.clues.length===0?'Start at the Royal Archive. The festival register has a story somebody tried to erase.':state.clues.length===6?'All six clues are ready. Open your journal and connect the evidence.':'Follow the evidence: manor, market merchant, hollow oak, orphanage, and carriage house.'}</p><span class="pill">${state.clues.length}/6 clues</span> <span class="pill">${state.crafted} pairs crafted</span><button id="questGo_original">Take me there →</button></div>`;$('people').textContent={capital:'Fern the innkeeper · Lady Mirelle Silverstitch',workshop:'Master Cobble · Liora the forest courier',market:'Merchant Elian · Moss the furniture maker',home:'Pip, your curious neighbor',academy:'Professor Thistle · Apprentice Rowan',forest:'Willow the woodland guardian',forgotten:'Archivist Rowan · Royal watchkeeper',festival:'Lantern keeper Aurelia'}[scene]}
