function exportProgress(){try{saveSystem.download({...state,scene});toast('Backup downloaded. Keep it somewhere safe.')}catch{toast('A backup could not be downloaded. Please try again.')}}
function restoreProgress(saved){
 const next={...fresh(),...saveSystem.validate(saved)};
 if(!saveSystem.blocked&&!saveSystem.write({...state,scene})){toast('Download a backup before restoring: browser storage is unavailable.');return false;}
 if(!saveSystem.write(next,true)){toast('Progress was not replaced because browser storage is unavailable.');return false;}
 state=next;scene=next.scene;
 if(window.onRealmSaveRestored)window.onRealmSaveRestored();else changeScene(scene);
 toast('Your saved progress has been restored');return true;
}
function saveBackups(){
 modal('Save & backups','<p>Your progress saves automatically in this browser on this website. Clearing site data or changing devices can remove it. Download a backup to keep a separate copy.</p>');
 const message=document.createElement('p');message.textContent=saveSystem.notice||'Automatic saving is ready.';$('modal').append(message);
 action('Download current progress',exportProgress);
 action('Restore a downloaded backup',()=>$('savefile').click());
 let backup;try{backup=saveSystem.backup()}catch{}
 if(backup){
  const details=document.createElement('p');details.textContent='Previous automatic backup: '+backup.coins+' mooncoins · '+scenes[backup.scene].name;$('modal').append(details);
  action('Download previous automatic backup',()=>saveSystem.download(backup,'Eldoria-previous-save.json'));
  action('Restore previous automatic backup',()=>{
   modal('Restore previous progress?','<p>This returns to the previous automatic backup. Your current saved progress will become the fallback backup.</p>');
   action('Restore this backup',()=>restoreProgress(backup));action('Keep current progress',saveBackups);
  });
 }
 if(saveSystem.blocked)action('Start a new save',()=>{
  modal('Start a new save?','<p>Your unreadable save will be kept in this browser for recovery. Start over only if you cannot restore a downloaded backup.</p>');
  action('Keep trying to restore',saveBackups);action('Start over and keep the old save',()=>{const next=fresh();if(!saveSystem.startNew(next))return;state=next;scene=next.scene;if(window.onRealmSaveRestored)window.onRealmSaveRestored();else changeScene(scene);});
 });
}
$('save').onclick=exportProgress;$('import').onclick=()=>$('savefile').click();$('saveBackups').onclick=saveBackups;
$('savefile').onchange=async e=>{
 const input=e.target,file=input.files?.[0];if(!file)return false;
 try{
  if(file.size>saveSystem.limit)throw Error('File too large');
  const saved=saveSystem.parse(await file.text());return restoreProgress(saved);
 }catch{toast('That backup could not be read. Your current progress has not been replaced.');return false;}
 finally{input.value='';}
};
